// ============================================================================
// GET ACTIVE WORKFLOWS — pagination du curseur (azy.daily#459)
// ============================================================================
//
// ⚠️ CE NŒUD ÉTAIT UN httpRequest AVEC UN SEUL APPEL `?active=true&limit=250`.
// L'API n8n rend alors 250 workflows ET un `nextCursor` — que personne ne suivait.
//
// Mesuré le 2026-10-01 : 258 workflows actifs, dont 245 porteurs de webhook.
// L'appel unique en rendait 250, et le registre publiait 218 outils au lieu de 226.
// HUIT OUTILS ÉTAIENT INVISIBLES de MCP, sans la moindre erreur : le registre
// répondait 200, annonçait son total, et ce total était faux.
//
//   MCP - Vector Store              Category Detect
//   SHOPPING---Cart-Checkout-Success  Credits Check
//   CHANNELS---Private-Register-Callback  DISCORD - Subscribe
//   MCP - Bulk URL Processor        Torah Translate Page
//
// Le défaut s'aggrave tout seul : chaque workflow activé pousse un outil de plus
// au-delà de la frontière. Il était invisible parce que rien ne comparait jamais
// le nombre d'outils publiés au nombre d'outils existants.
//
// La sortie garde EXACTEMENT la forme attendue par `Build Registry`
// (`$input.first().json.data`), donc rien d'autre ne change dans ce workflow.

const cleApi = $('Webhook Registry').first().json.headers['x-n8n-api-key'];
const base = ($env.N8N_API_URL || '').replace(/\/+$/, '');

// Garde-fou : un curseur qui ne progresse pas boucherait le registre indéfiniment.
// 20 pages de 250 = 5000 workflows, très au-delà du parc, et l'arrêt est explicite.
const MAX_PAGES = 20;

const tous = [];
const vus = new Set();
let curseur = null;
let pages = 0;
let tronque = false;

do {
  const url = base + '/workflows?active=true&limit=250'
    + (curseur ? '&cursor=' + encodeURIComponent(curseur) : '');
  const reponse = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: { 'X-N8N-API-KEY': cleApi },
    json: true,
  });
  // Un même workflow peut revenir sur deux pages si le parc bouge pendant la
  // pagination : on dédoublonne par id plutôt que de publier un outil deux fois.
  for (const wf of (reponse && reponse.data) || []) {
    if (!vus.has(wf.id)) { vus.add(wf.id); tous.push(wf); }
  }
  curseur = (reponse && reponse.nextCursor) || null;
  pages += 1;
  if (curseur && pages >= MAX_PAGES) { tronque = true; break; }
} while (curseur);

return [{
  json: {
    data: tous,
    // Diagnostic : si `tronque` passe à true un jour, le registre MENT à nouveau.
    // Mieux vaut que ça se lise dans la réponse que de le redécouvrir dans six mois.
    _pagination: { pages: pages, workflows: tous.length, tronque: tronque },
  },
}];

// ============================================================================
// BUILD REGISTRY - Extract metadata from workflows
// Version 4.4 - Added analyzable and category parsing from sticky notes
// ============================================================================

const workflows = $input.first().json.data || [];
// L'hôte publié doit être celui par lequel l'appelant nous a joints : ces URL
// partent chez MCP, qui tourne sur une autre machine ; l'ancien hôte codé
// en dur est décommissionné.
const hoteAppelant = $('Webhook Registry').first().json.headers?.host;
const baseUrl = $env.WEBHOOK_URL || (hoteAppelant ? `http://${hoteAppelant}/` : 'http://llm.local:5678/');

// Filter: active + has webhook + not TORAH/Registry
const toolWorkflows = workflows.filter(w =>
  w.active &&
  !w.name.includes('Registry') &&
  !w.name.includes('TORAH')
);

// Build tools object
const tools = {};

for (const workflow of toolWorkflows) {
  const webhookNode = workflow.nodes?.find(n => n.type === 'n8n-nodes-base.webhook');

  if (webhookNode) {
    const webhookPath = webhookNode.parameters?.path || webhookNode.webhookId;

    // Extract description from sticky note
    const stickyNote = workflow.nodes?.find(n => n.type === 'n8n-nodes-base.stickyNote');
    const stickyContent = stickyNote?.parameters?.content || '';

    // Parse description from sticky (after "Description:")
    const descMatch = stickyContent.match(/\*\*Description[:\s]*\*\*\s*\n?([^\n*]+)/i);
    const description = descMatch ? descMatch[1].trim() : workflow.name;

    // Parse InputSchema from sticky note (JSON block after **InputSchema:**)
    let parameters = { type: 'object', required: [], properties: {} };
    const schemaMatch = stickyContent.match(/\*\*InputSchema:\*\*\s*```json\s*([\s\S]*?)```/i);
    if (schemaMatch) {
      try {
        const inputSchema = JSON.parse(schemaMatch[1].trim());
        parameters.required = inputSchema.required || [];
        parameters.properties = inputSchema.properties || {};
      } catch (e) {
        // Invalid JSON in InputSchema, keep empty parameters
      }
    }

    // Parse Analyzable from sticky note (JSON block after **Analyzable:**)
    // Format: { accepts_image: bool, output_fields: [], domain: string }
    let analyzable = null;
    const analyzableMatch = stickyContent.match(/\*\*Analyzable:\*\*\s*```json\s*([\s\S]*?)```/i);
    if (analyzableMatch) {
      try {
        analyzable = JSON.parse(analyzableMatch[1].trim());
      } catch (e) {
        // Invalid JSON in Analyzable, keep null
      }
    }

    // Parse Category from sticky note (inline after **Category:**)
    const categoryMatch = stickyContent.match(/\*\*Category:\*\*\s*([^\n*]+)/i);
    const category = categoryMatch ? categoryMatch[1].trim().toLowerCase() : null;

    // Extract scope from settings or default to "user"
    const scope = workflow.settings?.scope || 'user';

    // Extract tags from workflow tags or name
    const tags = workflow.tags?.map(t => t.name) || [];

    const toolEntry = {
      name: workflow.name,
      description: description,
      workflow_id: workflow.id,
      endpoint: `/webhook/${webhookPath}`,
      webhook_url: `${baseUrl}webhook/${webhookPath}`,
      method: webhookNode.parameters?.httpMethod || "POST",
      scope: scope,
      tags: tags,
      parameters: parameters,
      active: workflow.active
    };

    // Add category if found
    if (category) {
      toolEntry.category = category;
    }

    // Add analyzable if found (for PipelineExecutor)
    if (analyzable) {
      toolEntry.analyzable = analyzable;
    }

    tools[webhookPath] = toolEntry;
  }
}

return {
  json: {
    version: "4.4",
    updated_at: new Date().toISOString(),
    total_tools: Object.keys(tools).length,
    tools: tools
  }
};

